// Original teaching set. Mechanics are abstractions, not operational instructions.
const cards=[];
function add(faction,name,cost,type,text,lesson,extra={}){const id=(faction[0]+cards.filter(c=>c.faction===faction).length);cards.push({id,faction,name,cost,type,text,lesson,...extra,art:`cards/${name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}`});}
const R=(...a)=>add('red',...a),B=(...a)=>add('blue',...a);
R('Relay Node',0,'Infrastructure','Tap: Add 1 compute.','Attack campaigns depend on infrastructure. Disrupting that infrastructure can limit an operation.');
R('Recon Operator',1,'Unit','', 'Reconnaissance helps an adversary identify exposed systems and likely entry points.',{power:1,toughness:2,subtype:'Operator'});
R('Credential Broker',2,'Unit','Lifelink','Stolen identities can sustain an attack campaign. Lifelink represents this advantage, not literal recovery.',{power:2,toughness:1,keywords:['lifelink'],subtype:'Identity'});
R('Phishing Courier',2,'Unit','Haste. Phishing.','Phishing pressures people into revealing information or approving access. Verify unexpected requests independently.',{power:2,toughness:1,keywords:['haste'],tags:['phishing'],subtype:'Social engineering'});
R('Payload Runner',2,'Unit','', 'An initial foothold may enable additional malicious components. Layered defenses matter.',{power:2,toughness:2,subtype:'Malware'});
R('Rogue Access Point',3,'Unit','Flying','An untrusted wireless network can expose traffic or mislead users. Flying models a different attack path.',{power:2,toughness:2,keywords:['flying'],subtype:'Network'});
R('Session Hijacker',3,'Unit','Haste','A stolen session token may bypass a fresh login. Session protection and revocation complement MFA.',{power:3,toughness:1,keywords:['haste'],subtype:'Identity'});
R('Lateral Mover',3,'Unit','', 'Segmentation and limited privileges can constrain movement after an initial compromise.',{power:3,toughness:3,subtype:'Operator'});
R('Persistence Agent',4,'Unit','Vigilance','Persistence lets an adversary retain access. Removing one visible symptom may not remove every foothold.',{power:3,toughness:4,keywords:['vigilance'],subtype:'Malware'});
R('Supply Chain Implant',4,'Unit','Flying','Trusted software and vendors can become attack paths. Provenance and monitoring remain important.',{power:3,toughness:3,keywords:['flying'],subtype:'Malware'});
R('Exfiltration Drone',4,'Unit','Flying. Lifelink','Data theft can be an objective independently of service disruption. Monitor unusual data movement.',{power:2,toughness:3,keywords:['flying','lifelink'],subtype:'Network'});
R('Ransomware Engine',5,'Unit','Trample','Ransomware can combine disruption and data theft. Tested recovery is one layer of preparation.',{power:5,toughness:4,keywords:['trample'],subtype:'Malware'});
R('Campaign Architect',6,'Unit','Vigilance','Attack campaigns coordinate multiple techniques. A single control rarely addresses every stage.',{power:5,toughness:6,keywords:['vigilance'],subtype:'Operator'});
R('Credential Phishing',2,'Operation','Deal 3 damage to the opponent. Phishing.','Phishing-resistant MFA reduces the risk of stolen credentials being reused. It does not stop all social engineering.',{effect:'damage',amount:3,target:'opponent',tags:['phishing']});
R('Exploit Window',2,'Response','Deal 3 damage to target unit.','A delay between exposure and remediation creates an opportunity for exploitation.',{effect:'damage',amount:3,target:'unit'});
R('Disrupt Telemetry',2,'Response','Counter target Response or Operation.','Loss of visibility can delay detection and response. Countering a card is a game abstraction.',{effect:'counter',target:'spell'});
R('Open Source Recon',2,'Operation','Draw two cards.','Public information can inform both defenders and attackers. Review unnecessary information exposure.',{effect:'draw',amount:2});
R('Denial of Service',4,'Operation','Deal 4 damage to the opponent.','Availability attacks exhaust resources. Resilience requires capacity planning and appropriate mitigation.',{effect:'damage',amount:4,target:'opponent'});
R('Token Replay',2,'Response','Return target unit to its owner’s hand.','Reusing a captured token can extend unauthorized access. Token expiry and revocation limit exposure.',{effect:'bounce',target:'unit'});
R('Privilege Escalation',2,'Response','Target unit gets +3/+1 until end of turn.','Excess permissions can amplify a foothold. Least privilege limits the resulting impact.',{effect:'buff',powerBoost:3,toughnessBoost:1,target:'unit'});
R('Erase Evidence',4,'Operation','Destroy target unit.','Tampering with evidence complicates investigations. Protected and centralized logs improve resilience.',{effect:'destroy',target:'unit'});
R('Rebuild Foothold',3,'Operation','Return target unit card from your discard to your hand.','A campaign may re-establish access if underlying weaknesses remain unresolved.',{effect:'recover',target:'grave'});
R('Botnet Reserve',3,'Tool','At the beginning of your upkeep, gain 1 operational capacity.','Redundant infrastructure can sustain an adversary. Disruption often needs coordination.',{effect:'upkeepHeal',amount:1});
R('Command Channel',3,'Control','Your units get +1/+0.','Command channels coordinate activity. Detecting or interrupting them can constrain operations.',{effect:'anthem',powerBoost:1,toughnessBoost:0});
R('Disable Safeguard',2,'Operation','Destroy target Tool or Control.','An attacker may attempt to disable safeguards. Monitor changes to security settings.',{effect:'destroy',target:'support'});
B('Secure Datacenter',0,'Infrastructure','Tap: Add 1 compute.','Reliable infrastructure supports security operations. Resources must be maintained and prioritized.');
B('SOC Trainee',1,'Unit','', 'Security operations start with triage: establish context before escalating an alert.',{power:1,toughness:2,subtype:'Analyst'});
B('Endpoint Sensor',2,'Unit','Reach','Endpoint telemetry adds visibility into suspicious activity. It must be configured and monitored.',{power:1,toughness:3,keywords:['reach'],subtype:'Service'});
B('Incident Responder',2,'Unit','Vigilance','Responders contain incidents while preserving the information needed to understand them.',{power:2,toughness:2,keywords:['vigilance'],subtype:'Analyst'});
B('Awareness Champion',2,'Unit','Lifelink','Prompt reporting helps an organization respond. Encourage reporting without blame.',{power:2,toughness:1,keywords:['lifelink'],subtype:'Analyst'});
B('Network Sentinel',3,'Unit','Flying','Network monitoring can reveal unusual connections, but encrypted traffic and context affect visibility.',{power:2,toughness:3,keywords:['flying'],subtype:'Service'});
B('Threat Hunter',3,'Unit','Haste','Threat hunting proactively tests hypotheses using available evidence.',{power:3,toughness:2,keywords:['haste'],subtype:'Analyst'});
B('Segmentation Gateway',3,'Unit','Defender. Reach','Network segmentation limits reachability and can reduce the scope of a compromise.',{power:1,toughness:5,keywords:['defender','reach'],subtype:'Service'});
B('Forensic Investigator',4,'Unit','Vigilance','Preserving evidence helps reconstruct events and avoid premature conclusions.',{power:3,toughness:4,keywords:['vigilance'],subtype:'Analyst'});
B('Identity Guardian',4,'Unit','Flying','Identity controls need to consider enrollment, authentication, active sessions, and account recovery.',{power:3,toughness:3,keywords:['flying'],subtype:'Service'});
B('Recovery Engineer',4,'Unit','Lifelink','Recovery requires verified backups, clean restore points, and rehearsed procedures.',{power:3,toughness:3,keywords:['lifelink'],subtype:'Analyst'});
B('Containment Team',5,'Unit','Vigilance','Containment limits impact while teams assess eradication and safe recovery.',{power:4,toughness:5,keywords:['vigilance'],subtype:'Analyst'});
B('Resilience Architect',6,'Unit','Trample','Resilience combines prevention, detection, response, and recovery. Trample represents coordinated disruption of red’s campaign.',{power:5,toughness:6,keywords:['trample'],subtype:'Analyst'});
B('Revoke Sessions',2,'Response','Return target unit to its owner’s hand.','Revoking active sessions can cut off token-based access. Password resets alone may not invalidate every session.',{effect:'bounce',target:'unit'});
B('Emergency Patch',2,'Response','Deal 3 damage to target unit.','Timely remediation reduces exposure to known vulnerabilities. Validate and prioritize patches by risk.',{effect:'damage',amount:3,target:'unit'});
B('Block Execution',2,'Response','Counter target Response or Operation.','Execution controls can interrupt malicious activity. Their coverage depends on configuration and context.',{effect:'counter',target:'spell'});
B('Correlate Logs',2,'Operation','Draw two cards.','Correlating events from several sources provides context that isolated alerts may miss.',{effect:'draw',amount:2});
B('Disrupt Infrastructure',4,'Operation','Deal 4 damage to the opponent.','Coordinated disruption can reduce an adversary’s capacity to continue a campaign.',{effect:'damage',amount:4,target:'opponent'});
B('Restore Backup',2,'Response','Gain 4 operational capacity.','Backups are useful only if they are recoverable. Test restores and protect backup access.',{effect:'heal',amount:4});
B('Least Privilege',2,'Response','Target unit gets -3/+0 until end of turn.','Limiting permissions reduces what a compromised identity or process can do.',{effect:'buff',powerBoost:-3,toughnessBoost:0,target:'unit'});
B('Isolate Host',4,'Operation','Destroy target unit.','Host isolation can limit spread while responders investigate. Operational impact must be considered.',{effect:'destroy',target:'unit'});
B('Clean Rebuild',3,'Operation','Return target unit card from your discard to your hand.','Rebuilding from trusted sources can support recovery after compromise; address the original entry point too.',{effect:'recover',target:'grave'});
B('Immutable Backup',3,'Tool','At the beginning of your upkeep, gain 1 operational capacity.','Immutability helps protect restore points. Retention, access controls, and recovery testing still matter.',{effect:'upkeepHeal',amount:1});
B('Phishing-Resistant MFA',3,'Control','Prevent damage to you from sources with Phishing.','This game models resistance to credential phishing only. Session theft, recovery abuse, and other attacks need additional controls.',{effect:'antiPhishing'});
B('Configuration Audit',2,'Operation','Destroy target Tool or Control.','Regular reviews can identify unsafe configurations and unauthorized changes.',{effect:'destroy',target:'support'});
export const CARDS=cards;
export const BY_ID=Object.fromEntries(cards.map(c=>[c.id,c]));
export function deck(faction){const set=cards.filter(c=>c.faction===faction);return [...Array(24).fill(set[0].id),...set.filter(c=>c.type==='Unit').flatMap(c=>[c.id,c.id]),...set.filter(c=>!['Unit','Infrastructure'].includes(c.type)).map(c=>c.id)];}
export const KEYWORDS={haste:'May attack the turn it enters.',vigilance:'Attacking does not tap this unit.',flying:'Can only be blocked by units with flying or reach.',reach:'Can block units with flying.',lifelink:'Damage dealt by this unit also gains you that much capacity.',trample:'Excess combat damage can reach the opponent after lethal damage is assigned to blockers.',defender:'Cannot attack.'};
